import pandas as pd
import numpy as np

df = pd.read_csv('/app/dataset/synthetic_stroke_data.csv')
df['orig_idx'] = df.index

outlier_set = set()
for _, row in df.iterrows():
    idx = int(row['orig_idx'])
    age = row['age']; bmi = row['bmi']; avg = row['avg_glucose_level']
    if pd.isna(age) or pd.isna(bmi) or pd.isna(avg):
        outlier_set.add(idx); continue
    if age > 120: outlier_set.add(idx)
    if bmi < 10 or bmi > 60: outlier_set.add(idx)
    if avg < 20 or avg > 800: outlier_set.add(idx)

# Apply 3*IQR on relevant columns
def iqr_mask(s):
    q1 = s.quantile(0.25); q3 = s.quantile(0.75)
    iqr = q3 - q1
    if iqr == 0: return pd.Series([False] * len(s), index=s.index)
    lo = q1 - 3*iqr; hi = q3 + 3*iqr
    return (s < lo) | (s > hi)

